-- the server setters create the entity at once, without owner (-1) until a player is in scope
---@param self fx.Entity
---@param timeoutMs? integer
---@param waitOwner? boolean
---@return fx.Promise<fx.Entity>
methods.readyAsync = function(self, timeoutMs, waitOwner)
  local h = self.handle
  return rt.waitUntil(tostring(self) .. ":readyAsync", function()
    if not DoesEntityExist(h) then return false end
    return waitOwner == false or NetworkGetEntityOwner(h) ~= -1
  end, timeoutMs, self)
end

