-- No model streaming on the server: createRaw, then readyAsync(). Entities created by the server setters are not
-- garbage collected.
---@param label string
---@param raw fx.RawCreate
---@return fx.CreateAsync
function rt.makeCreate(label, raw)
  return function(model, position, heading, options)
    local hash = rt.hash(model)
    if type(hash) ~= "number" then
      return P.reject(newError("Error", ("%s: invalid model '%s'"):format(label, tostring(model))))
    end
    local e = raw(hash, position, heading, options)
    if not e then
      return P.reject(newError("Error", ("%s: creation failed for model '%s' (no free object id, or invalid arguments)"):format(label, tostring(model))))
    end
    return e:readyAsync(options and options.timeout, not (options and options.waitOwner == false)):next(nil, function(err)
      -- nobody holds the wrapper: a server-setter entity left behind is never cleaned up
      if DoesEntityExist(e.handle) then DeleteEntity(e.handle) end
      rt.forget(e)
      return P.reject(err)
    end)
  end
end

---@param position vector3|vector4
---@param heading? number Default: the w of a vector4, else 0.0
---@return number
function rt.heading(position, heading)
  -- always a float: an integer reaches a float parameter as raw bits
  if heading ~= nil then return heading + 0.0 end
  if type(position) == "vector4" then return position.w + 0.0 end
  return 0.0
end

